// ---------------------------------------------------------------------------
// 2. BRIDGE — with mcpServers stdio normalization (ACP stdio shape)
// ---------------------------------------------------------------------------
hdr("2. Deploy acp-tcp-bridge");

const BRIDGE_SOURCE = `#!/usr/bin/env node
// acp-tcp-bridge — TCP<->stdio ACP bridge
// Normalizes mcpServers to the ACP stdio shape (type, name, command, args, env)
// expected by Kimi/Hermes/OMP, and injects mcpServers: [] when omitted.
const net = require("net");
const { spawn } = require("child_process");
const { Transform } = require("stream");

const args = process.argv.slice(2);
let port = 25111;
const pIdx = args.indexOf("--port");
let cmdStart = -1;
if (pIdx !== -1 && args[pIdx + 1]) { port = parseInt(args[pIdx + 1], 10); cmdStart = args.indexOf("--", pIdx) + 1; }
else { cmdStart = args.indexOf("--") + 1; }
if (cmdStart <= 0 || cmdStart >= args.length) { console.error("Usage: acp-tcp-bridge [--port <port>] -- <cmd> [args...]"); process.exit(1); }
const cmd = args.slice(cmdStart);

function normalizeServer(s) {
  return {
    type: typeof s?.type === "string" ? s.type : "stdio",
    name: typeof s?.name === "string" ? s.name : "",
    command: typeof s?.command === "string" ? s.command : "",
    args: Array.isArray(s?.args) ? s.args : [],
    env: Array.isArray(s?.env) ? s.env : [],
  };
}

const normalize = new Transform({
  transform(chunk, _enc, cb) {
    const lines = chunk.toString().split("\\n");
    const out = lines.map((line) => {
      if (!line.trim()) return line;
      try {
        const msg = JSON.parse(line);
        if ((msg.method === "session/new" || msg.method === "session/load") && msg.params) {
          if (msg.params.mcpServers === undefined) {
            msg.params.mcpServers = [];
          } else if (Array.isArray(msg.params.mcpServers)) {
            msg.params.mcpServers = msg.params.mcpServers.map(normalizeServer);
          }
        }
        return JSON.stringify(msg);
      } catch { return line; }
    }).join("\\n");
    cb(null, out);
  },
});

let seq = 0;
const server = net.createServer((sock) => {
  const cid = ++seq;
  let child = null, closed = false;
  const cleanup = () => {
    if (closed) return; closed = true;
    if (child && !child.killed) try { child.kill("SIGTERM"); } catch {}
    try { sock.destroy(); } catch {}
  };
  try {
    child = spawn(cmd[0], cmd.slice(1), { stdio: ["pipe", "pipe", "inherit"], env: process.env });
    child.on("error", (e) => { console.error(\`[acp-tcp-bridge] #\${cid} spawn error: \${e.message}\`); cleanup(); });
    sock.pipe(normalize).pipe(child.stdin);
    child.stdout.pipe(sock);
    sock.on("error", cleanup);
    sock.on("close", cleanup);
    child.on("close", () => { if (!closed) sock.end(); });
  } catch (e) { console.error(\`[acp-tcp-bridge] #\${cid} exception: \${e.message}\`); cleanup(); }
});
server.on("error", (e) => { console.error("[acp-tcp-bridge] server error:", e.message); process.exit(1); });
server.listen(port, "127.0.0.1", () => console.log(\`[acp-tcp-bridge] Listening 127.0.0.1:\${port} -> \${cmd.join(" ")}\`));
`;

if (fs.existsSync(BRIDGE_PATH)) fs.copyFileSync(BRIDGE_PATH, `${BRIDGE_PATH}.bak.${Date.now()}`);
fs.writeFileSync(BRIDGE_PATH, BRIDGE_SOURCE, { mode: 0o755 });
ok(`${BRIDGE_PATH} (hash ${H(BRIDGE_SOURCE)})`);

