// 4. PITCHFORK CONFIG
// ---------------------------------------------------------------------------
hdr("4. Repair pitchfork.toml");

const expectedRun = `run = "exec ${BRIDGE_PATH} --port ${PORT} -- ${OMP_BIN} acp -e ${EXT_PATH}"`;

function repairBlock(filepath, removeBlock = false) {
  if (!fs.existsSync(filepath)) { warn(`${filepath} not found`); return; }
  const raw = fs.readFileSync(filepath, "utf-8");
  const lines = raw.split("\n");
  const idx = lines.findIndex((l) => l.trim() === "[daemons.tau]");
  if (idx === -1) { warn(`[daemons.tau] not found in ${filepath}`); return; }

  let end = lines.length;
  for (let i = idx + 1; i < lines.length; i++) if (lines[i].trim().startsWith("[")) { end = i; break; }

  if (removeBlock) {
    const out = [...lines.slice(0, idx), ...lines.slice(end)].join("\n");
    if (out !== raw) {
      fs.copyFileSync(filepath, `${filepath}.bak.${Date.now()}`);
      fs.writeFileSync(filepath, out);
      ok(`Removed duplicate [daemons.tau] from ${filepath}`);
    } else warn(`No change to ${filepath}`);
    return;
  }

  const section = lines.slice(idx + 1, end);
  const cleaned: string[] = [];
  let hasRun = false, hasEnv = false, hasPort = false, hasDir = false;

  for (const line of section) {
    const t = line.trim();
    if (t.startsWith("run =") || t.startsWith("run=")) { if (!hasRun) { cleaned.push(expectedRun); hasRun = true; } continue; }
    if (t.startsWith("env =") || t.startsWith("env=")) {
      if (!hasEnv) {
        cleaned.push(`env = { PI_CONFIG_DIR = "/home/toxic/.tau", PI_AGENT_DIR = "/home/toxic/.tau/agent", PI_CODING_AGENT = "true", PI_REASONING_LEVEL = "high", PI_SUBAGENT_MODEL = "thinkingmachines/inkling", PI_OPENAI_STREAM_IDLE_TIMEOUT_MS = "120000", VANSROUTER_API_KEY = "local-sovereign" }`);
        hasEnv = true;
      }
      continue;
    }
    if (t.startsWith("port =") || t.startsWith("port=")) { hasPort = true; cleaned.push(`port = ${PORT}`); continue; }
    if (t.startsWith("dir =") || t.startsWith("dir=")) { hasDir = true; cleaned.push(`dir = "/home/toxic"`); continue; }
    cleaned.push(line);
  }
  if (!hasRun) cleaned.unshift(expectedRun);
  if (!hasEnv) cleaned.push(`env = { VANSROUTER_API_KEY = "local-sovereign" }`);
  if (!hasPort) cleaned.splice(hasDir ? cleaned.findIndex((l) => l.trim().startsWith("dir =")) : cleaned.length, 0, `port = ${PORT}`);

  const out = [...lines.slice(0, idx + 1), ...cleaned, ...lines.slice(end)].join("\n");
  if (out !== raw) {
    fs.copyFileSync(filepath, `${filepath}.bak.${Date.now()}`);
    fs.writeFileSync(filepath, out);
    ok(`Rewrote [daemons.tau] in ${filepath} (hash ${H(out)})`);
  } else warn(`${filepath} already correct`);
}

repairBlock(PITCH_CANON, false);
repairBlock(PITCH_DUP, true);

// ---------------------------------------------------------------------------
// 5. RESTART
// ---------------------------------------------------------------------------
hdr("5. Restart sovereign/tau");
console.log(sh(`pitchfork clean --daemon sovereign/tau 2>&1 || true`));
console.log(sh(`cd /home/toxic/estate && pitchfork restart sovereign/tau 2>&1 | tail -8`));

// ---------------------------------------------------------------------------
// 6. VERIFY LISTENER (bounded, with DNS preflight already done)
// ---------------------------------------------------------------------------
hdr("6. Verify port listener");
await new Promise((r) => setTimeout(r, 3000));
console.log(sh(`ss -tlnp '( sport = :${PORT} )' 2>&1`));

