try {
  const stats = (globalThis as any).Bun?.dns?.getCacheStats?.();
  if (stats) info(`Bun DNS cache: size=${stats.size} hits=${stats.cacheHitsCompleted} misses=${stats.cacheMisses} errors=${stats.errors}`);
} catch {}

// ---------------------------------------------------------------------------
// 7. PROBE
// ---------------------------------------------------------------------------
hdr("7. Run end-to-end probe");
try {
  execSync(`bun ${PROBE_PATH}`, { stdio: "inherit" });
} catch {
  err("Probe failed. Check logs:");
  console.log(sh(`pitchfork logs sovereign/tau --raw -n 40 --no-pager 2>&1 | tail -40`));
  process.exit(1);
}

hdr("DONE");
console.log(`${C.green}All artifacts at first-class paths:${C.reset}`);
console.log(`  extension : ${EXT_PATH}`);
console.log(`  bridge    : ${BRIDGE_PATH}`);
console.log(`  probe     : ${PROBE_PATH}`);
console.log(`  config    : ${PITCH_CANON}`);
console.log(`\nRe-run anytime: ${C.bold}bun ${PROBE_PATH}${C.reset}\n`);
