#!/usr/bin/env node
// chute — TCP<->stdio ACP passage for the herd.
// Entry point. Parses argv, dispatches to check or serve.
import { parseArgs } from "./src/args.mjs";
import { runCheck } from "./src/check.mjs";
import { createChuteServer } from "./src/server.mjs";
import { log } from "./src/log.mjs";

const args = parseArgs(process.argv.slice(2));

if (args.check) {
  const r = await runCheck();
  process.stdout.write(JSON.stringify(r) + "\n");
  process.exit(r.ready ? 0 : 1);
}

if (!args.valid) {
  console.error("Usage: chute [--port <port>] [--check] -- <cmd> [args...]");
  process.exit(1);
}

const { listen } = createChuteServer({ port: args.port, cmd: args.cmd });
listen();
log("", `started port=${args.port} cmd=${args.cmd.join(" ")}`);

